create table public.roles(id uuid primary key default gen_random_uuid(),name text unique not null,description text,system boolean not null default false);
create table public.permissions(key text primary key,description text not null);
create table public.role_permissions(role_id uuid references roles(id) on delete cascade,permission_key text references permissions(key) on delete cascade,primary key(role_id,permission_key));
create table public.admin_roles(profile_id uuid references profiles(id) on delete cascade,role_id uuid references roles(id) on delete cascade,assigned_by uuid references profiles(id),created_at timestamptz default now(),primary key(profile_id,role_id));
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references profiles(id),action text not null,entity_type text not null,entity_id text,old_data jsonb,new_data jsonb,ip_hash text,created_at timestamptz not null default now());
create table public.security_logs(id bigint generated always as identity primary key,profile_id uuid references profiles(id),event text not null,risk text not null default 'low',ip_hash text,user_agent text,metadata jsonb default '{}',created_at timestamptz default now());
create table public.profile_change_history(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),changed_by uuid references profiles(id),changes jsonb not null,significant boolean not null,created_at timestamptz default now());
create table public.articles(id uuid primary key default gen_random_uuid(),slug text unique not null,status text not null default 'draft',author_id uuid references profiles(id),published_at timestamptz,created_at timestamptz default now());
create table public.article_translations(article_id uuid references articles(id) on delete cascade,locale text not null,title text not null,excerpt text,body text not null,seo jsonb default '{}',primary key(article_id,locale));
create table public.site_pages(id uuid primary key default gen_random_uuid(),slug text unique not null,status text not null default 'draft',updated_at timestamptz default now());
create table public.site_translations(page_id uuid references site_pages(id) on delete cascade,locale text not null,title text not null,content jsonb not null default '{}',seo jsonb default '{}',primary key(page_id,locale));
create table public.media(id uuid primary key default gen_random_uuid(),storage_path text unique not null,mime_type text not null,size_bytes bigint not null,alt_translations jsonb default '{}',uploaded_by uuid references profiles(id),created_at timestamptz default now());
create table public.ai_interactions(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id),task text not null,provider text not null,model text not null,input_hash text not null,grounding_ids jsonb,response text,status text not null,confirmed_at timestamptz,created_at timestamptz default now());
create table public.settings(key text primary key,value jsonb not null,public boolean not null default false,updated_by uuid references profiles(id),updated_at timestamptz default now());
insert into public.settings(key,value,public) values ('portfolio_limits','{"images":6,"videos":3,"image_bytes":10485760,"video_bytes":104857600}',true),('commission','{"deduction_bps":700}',false),('moderation','{"maximum_review_hours":24,"target_review_minutes":60}',true);
create or replace function public.has_permission(required text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from admin_roles ar join role_permissions rp on rp.role_id=ar.role_id where ar.profile_id=auth.uid() and (rp.permission_key=required or rp.permission_key='*'))$$;
create or replace function public.guard_account_type() returns trigger language plpgsql as $$begin if old.account_type<>new.account_type then raise exception 'Primary account type cannot be changed'; end if;return new;end$$;
create trigger immutable_account_type before update on profiles for each row execute function guard_account_type();
create or replace function public.prevent_audit_mutation() returns trigger language plpgsql as $$begin raise exception 'Audit logs are append-only';end$$;
create trigger audit_immutable before update or delete on audit_logs for each row execute function prevent_audit_mutation();
-- Enable RLS on every user-facing table. Service-role access remains server-only.
do $$declare t text;begin foreach t in array array['profiles','individual_profiles','team_profiles','client_profiles','team_members','profile_skills','profile_details','portfolios','portfolio_media','profile_drafts','verification_requests','appointments','work_requests','work_request_skills','work_request_invites','offers','projects','project_agreements','project_deliveries','project_files','chat_rooms','chat_participants','chat_messages','message_moderation','transactions','payments','ledger_entries','payouts','disputes','dispute_evidence','appeals','reviews','favorites','notifications','admin_roles','audit_logs','security_logs','profile_change_history','articles','article_translations','site_pages','site_translations','media','ai_interactions','settings'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "own profile" on profiles for select using(id=auth.uid() or public.has_permission('users.read'));
create policy "update own active profile" on profiles for update using(id=auth.uid() and account_status='active') with check(id=auth.uid());
create policy "authenticated verified talent directory" on individual_profiles for select to authenticated using(verification_status='verified' or profile_id=auth.uid() or has_permission('users.read'));
create policy "authenticated verified teams" on team_profiles for select to authenticated using(verification_status='verified' or profile_id=auth.uid() or has_permission('users.read'));
create policy "own individual" on individual_profiles for all using(profile_id=auth.uid()) with check(profile_id=auth.uid());
create policy "own team" on team_profiles for all using(profile_id=auth.uid()) with check(profile_id=auth.uid());
create policy "own client" on client_profiles for all using(profile_id=auth.uid()) with check(profile_id=auth.uid());
create policy "participants see projects" on projects for select using(auth.uid() in(client_id,talent_id) or has_permission('projects.read'));
create policy "offer privacy" on offers for select using(talent_id=auth.uid() or exists(select 1 from work_requests w where w.id=work_request_id and w.client_id=auth.uid()) or has_permission('offers.read'));
create policy "room participant messages" on chat_messages for select using(exists(select 1 from chat_participants cp where cp.room_id=chat_messages.room_id and cp.profile_id=auth.uid()) or has_permission('messages.review'));
create policy "room participant insert messages" on chat_messages for insert with check(sender_id=auth.uid() and exists(select 1 from chat_participants cp where cp.room_id=chat_messages.room_id and cp.profile_id=auth.uid()));
create policy "own notifications" on notifications for select using(profile_id=auth.uid());
create policy "transaction parties" on transactions for select using(auth.uid() in(client_id,talent_id) or has_permission('payments.read'));
create policy "public published articles" on articles for select using(status='published' or has_permission('content.edit'));
create policy "public article translations" on article_translations for select using(exists(select 1 from articles a where a.id=article_id and a.status='published') or has_permission('content.edit'));
create policy "public pages" on site_pages for select using(status='published' or has_permission('content.edit'));
create policy "public page translations" on site_translations for select using(exists(select 1 from site_pages p where p.id=page_id and p.status='published') or has_permission('content.edit'));
-- Private storage buckets; clients receive time-limited signed URLs from authorized server routes.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('portfolio','portfolio',false,104857600,array['image/jpeg','image/png','image/webp','video/mp4','video/webm']),('documents','documents',false,20971520,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']),('project-files','project-files',false,104857600,null),('message-files','message-files',false,52428800,array['image/jpeg','image/png','image/webp','application/pdf','audio/webm','audio/ogg']) on conflict(id) do nothing;
create policy "users upload own portfolio" on storage.objects for insert to authenticated with check(bucket_id='portfolio' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "users manage own documents" on storage.objects for all to authenticated using(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "authenticated directory profile cards" on profiles for select to authenticated using(exists(select 1 from individual_profiles i where i.profile_id=profiles.id and i.verification_status='verified') or exists(select 1 from team_profiles t where t.profile_id=profiles.id and t.verification_status='verified'));
create policy "verified team public members" on team_members for select to authenticated using(exists(select 1 from team_profiles t where t.profile_id=team_members.team_id and t.verification_status='verified') or team_id=auth.uid() or has_permission('users.read'));
create policy "own portfolio read" on portfolios for select to authenticated using(profile_id=auth.uid() or exists(select 1 from individual_profiles i where i.profile_id=portfolios.profile_id and i.verification_status='verified') or exists(select 1 from team_profiles t where t.profile_id=portfolios.profile_id and t.verification_status='verified'));
